def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
units=[];counts=Counter()
def add(category,page,locator,text,scope='Source-wide context; no exact physical batch established.',claim=None,**extra):
 counts[category]+=1
 claim=claim or {'identity':'verified_source_identity','chemical_inventory':'reported_material_identity','procedure':'reported_procedure','characterization_method':'reported_measurement_method','observation':'reported_observation','author_model':'author_interpretation_or_model','figure':'original_source_asset','table':'experimental_and_reference_values_separated','equation':'author_model','conflict':'source_conflict_or_missingness','reference':'cited_context_not_independently_read','intuition':'original_author_intuition'}.get(category,'reported_source_fact')
 pages=[page]if isinstance(page,int)else page
 u={'id':f'{category}-{counts[category]:02d}','category':category,'text':text,'sample_scope':scope,'claim_type':claim,'evidence':[{'source_id':'stiger1999','pdf_page':p,'printed_page':789+p,'locator':f'Main PDF p. {p}, printed p. {789+p}, {locator}'}for p in pages],**extra};units.append(u);return u
def rows(category,data,scope='Source-wide context; no exact physical batch established.'):
 for p,loc,t in data:add(category,p,loc,t,scope)
